def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Find the solid 2-colored boundary.
    boundary = None
    for r in range(h):
        if all(x == 2 for x in grid[r]):
            boundary = ("row", r)
            break
    if boundary is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                boundary = ("col", c)
                break
    if boundary is None:
        return [row[:] for row in grid]

    color_counts = Counter(x for row in grid for x in row if x != bg and x != 2)
    if not color_counts:
        return [row[:] for row in grid]
    obj_color = color_counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == obj_color]
    rmin, rmax = min(r for r, c in points), max(r for r, c in points)
    cmin, cmax = min(c for r, c in points), max(c for r, c in points)

    dr = dc = 0
    if boundary[0] == "row":
        br = boundary[1]
        if br > rmax:
            dr = br - 1 - rmax
        else:
            dr = br + 1 - rmin
    else:
        bc = boundary[1]
        if bc > cmax:
            dc = bc - 1 - cmax
        else:
            dc = bc + 1 - cmin

    out = [row[:] for row in grid]
    for r, c in points:
        out[r][c] = bg
    moved = [(r + dr, c + dc) for r, c in points]
    for r, c in moved:
        out[r][c] = obj_color

    if boundary[0] == "row":
        line = min(r for r, c in moved) - 1 if dr >= 0 else max(r for r, c in moved) + 1
        if 0 <= line < h:
            out[line] = [8] * w
    else:
        line = min(c for r, c in moved) - 1 if dc >= 0 else max(c for r, c in moved) + 1
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8
    return out
